 if(!source.hasKeyboardFocus(true))source.setText(state["sourceText"].toString(),false);key.setButtonText(state["tonality"]["tonic"].toString()+" "+state["tonality"]["mode"].toString());autoKey.setButtonText(state["harmony"]["keyMode"].toString()=="locked"?"Locked":"Auto");
