void KhimairaEditor::updatePlaybackDisplay(){if(processor.revision()!=lastRevision&&!source.hasKeyboardFocus(true)&&!chordText.hasKeyboardFocus(true))refresh();refreshing=true;
 const bool host=processor.hostPlaying.load();play.setEnabled(!host);stop.setEnabled(!host);play.setButtonText(processor.previewRequested.load()?"Stop":"Play");play.setToggleState(processor.previewRequested.load(),dontSendNotification);loop.setToggleState(processor.loop.load(),dontSendNotification);piano.setToggleState(processor.pianoEnabled.load(),dontSendNotification);sync.setToggleState(processor.syncTempo(),dontSendNotification);tempo.setEnabled(!processor.syncTempo()&&!host);tempo.setValue(host||processor.syncTempo()?processor.hostTempo.load():processor.userTempo(),dontSendNotification);anchor.setEnabled(startMode.getSelectedId()==2);swing.setEnabled(!processor.arpParameters().triplet());
 score.beat=processor.position.load();score.playing=processor.playing.load();score.repaint();if(following&&score.playing){for(auto& c:score.cells)if(score.beat>=c.beat&&score.beat<c.beat+c.beats){int x=scoreView.getViewPositionX();if(c.bounds.getX()<x||c.bounds.getRight()>x+scoreView.getWidth()-12)scoreView.moveTo((int)c.bounds.getX()-8);break;}}
 follow.setButtonText(following?"Following playhead":"Resume follow");follow.setToggleState(following,dontSendNotification);
 clock.setText((score.playing?"PLAYING":"READY")+String("  /  BAR ")+String(1+(int)std::max(0.,score.beat)/4)+"  /  "+String(state["bars"].size())+" BARS"+(host?juce::String::fromUTF8("  ·  DAW"):""),dontSendNotification);
 if(Time::getMillisecondCounterHiRes()>noticeUntil){String text=juce::String::fromUTF8("Space: play / stop   ·   Select a chord to edit   ·   Drag Export MIDI into your DAW");if(processor.waitingForStart.load())text="Waiting for next bar / start anchor";if(host&&processor.unsupportedMeter.load())text=juce::String::fromUTF8("Host playback requires 4/4 · MIDI muted");else if(host&&(!processor.hasHost.load()||!processor.hostTempoAvailable.load()))text=juce::String::fromUTF8("Waiting for DAW position and tempo · MIDI muted");if(processor.lastError.isNotEmpty())text=processor.lastError;status.setText(text,dontSendNotification);}refreshing=false;
}
bool KhimairaEditor::keyPressed(const KeyPress& k){if(source.hasKeyboardFocus(true)||chordText.hasKeyboardFocus(true))return false;if(k==KeyPress::spaceKey){play.onClick();return true;}if(k==KeyPress::escapeKey){stop.onClick();return true;}if((k==KeyPress::leftKey||k==KeyPress::rightKey)&&!score.cells.empty()){int current=0;for(size_t i=0;i<score.cells.size();i++)if(score.cells[i].bar==score.selectedBar&&score.cells[i].chord==score.selectedChord)current=(int)i;auto c=score.cells[(size_t)jlimit(0,(int)score.cells.size()-1,current+(k==KeyPress::rightKey?1:-1))];score.selectedBar=c.bar;score.selectedChord=std::max(0,c.chord);score.selected(c.bar,c.chord);following=false;scoreView.moveTo((int)c.bounds.getX()-8);return true;}if(k.getModifiers().isCommandDown()&&k.getTextCharacter()=='s'){projectFile(true);return true;}return false;}
void KhimairaEditor::keyMenu(){PopupMenu menu,transpose,candidates;StringArray names{"C","Db","D","Eb","E","F","F#","G","Ab","A","Bb","B"};for(int i=0;i<12;i++)transpose.addItem(i+1,names[i]);menu.addSubMenu(juce::String::fromUTF8("Transpose · preserve degrees"),transpose);auto list=state["candidates"];for(int i=0;i<list.size();i++)candidates.addItem(100+i,list[i]["tonic"].toString()+" "+list[i]["mode"].toString());menu.addSubMenu(juce::String::fromUTF8("Reinterpret · preserve pitches"),candidates);menu.addItem(200,juce::String::fromUTF8("Convert major / minor…"));menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&key),[safe=Component::SafePointer<KhimairaEditor>(this),list](int id){if(!safe||!id)return;if(id<100)safe->act("set",id-1,"key");else if(id<200)safe->act("reinterpret",list[id-100]);else AlertWindow::showOkCancelBox(MessageBoxIconType::QuestionIcon,"Convert tonality",String::fromUTF8("轉換大／小調會改變順階和弦性質，可 Undo 還原。"),"Convert","Cancel",safe.getComponent(),ModalCallbackFunction::create([safe](int yes){if(safe&&yes)safe->act("convertMode",object({{"mode",safe->state["mode"].toString()=="minor"?"major":"minor"},{"confirmed",true}}));}));});}
void KhimairaEditor::projectFile(bool saving){if(saving&&source.getText()!=state["sourceText"].toString())act("set",source.getText(),"sourceText");chooser=std::make_unique<FileChooser>(saving?"Save Khimaira project":"Open Khimaira project",File::getSpecialLocation(File::userDocumentsDirectory).getChildFile(saving?"Untitled.khimaira":""),"*.khimaira");chooser->launchAsync((saving?FileBrowserComponent::saveMode|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode)|FileBrowserComponent::canSelectFiles,[safe=Component::SafePointer<KhimairaEditor>(this),saving](const FileChooser& c){if(!safe||c.getResult()==File())return;auto f=c.getResult();if(saving){MemoryBlock data;safe->processor.getStateInformation(data);safe->notice(f.withFileExtension("khimaira").replaceWithData(data.getData(),data.getSize())?"Project saved":"Could not save project");}else{if(f.getSize()>8*1024*1024){safe->notice("Project exceeds 8 MB");return;}auto json=JSON::parse(f.loadFileAsString());if(!json["notes"].isArray()||!json["ui"]["harmony"].isObject()){safe->notice("Not a Khimaira native project");return;}auto result=safe->processor.update(json);if(!(bool)result["ok"]){safe->notice(result["message"].toString());return;}auto text=JSON::toString(json);safe->processor.setStateInformation(text.toRawUTF8(),(int)text.getNumBytesAsUTF8());safe->refresh();safe->notice(juce::String::fromUTF8("Project opened · playback stopped"));}});}
void KhimairaEditor::exportMidi(){auto temp=processor.midiFile();if(!temp.existsAsFile()){notice("MIDI export failed");return;}chooser=std::make_unique<FileChooser>("Save MIDI",File::getSpecialLocation(File::userDocumentsDirectory).getChildFile("Khimaira.mid"),"*.mid");chooser->launchAsync(FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting,[safe=Component::SafePointer<KhimairaEditor>(this),temp](const FileChooser& c){if(safe&&c.getResult()!=File())safe->notice(temp.copyFileTo(c.getResult().withFileExtension("mid"))?"MIDI saved":"Could not save MIDI");});}
